import contextlib

@contextlib.contextmanager
def fixed_file(filename):
    f = open(filename, 'r')
    try:
        yield f
    except Exception:
        f.close()
        raise
    else:
        f.close()

with fixed_file('data.txt') as f:
    print(f.read())

