import contextlib

@contextlib.contextmanager
def multi_resource(urls):
    handles = []
    try:
        for url in urls:
            handles.append(open(url, 'r'))
        yield handles
    finally:
        for h in handles:
            h.close()

with multi_resource(['a.txt', 'b.txt']) as handles:
    print(len(handles))

