            self.max_attempts -= 1
            return True
        return False

class LogFile:
    def __init__(self, path, mode='a'):
        self.path = path
        self.mode = mode
        self.handle = None

    def __enter__(self):
        self.handle = open(self.path, self.mode)
        return self.handle

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.handle is not None:
            self.handle.close()

# Scenario: log three events
